def build_program(d4,palette):
    source="import numpy as np\nBG=__BG__\nTC=__TC__\nDC=__DC__\n\ndef _triples(g):\n pts={tuple(map(int,p)) for p in np.argwhere(g==DC)};found=set();covered=set()\n for y,x in pts:\n  for vy in (-2,2):\n   for hx in (-2,2):\n    corners={(y,x),(y+vy,x),(y,x+hx)};missing=(y+vy,x+hx)\n    if corners<=pts and missing not in pts:\n     found.add((missing[0],missing[1],1 if vy>0 else -1,1 if hx>0 else -1));covered|=corners\n if covered!=pts or len(pts)!=3*len(found):return []\n return sorted(found)\n\ndef _origin(t,h,w):\n my,mx,dy,dx=t\n return (my if dy==1 else my-h+1,mx if dx==1 else mx-w+1)\n\ndef _outputs(grid,trim):\n g=np.asarray(grid);H,W=g.shape\n if set(g.ravel().tolist())-set((BG,TC,DC)):return []\n cells=np.argwhere(g==TC)\n if not len(cells):return []\n y0,x0=map(int,cells.min(axis=0));y1,x1=map(int,cells.max(axis=0));h,w=y1-y0+1,x1-x0+1\n if h!=w or h not in (2,3):return []\n triples=_triples(g)\n if not triples:return []\n owners=[t for t in triples if _origin(t,h,w)==(y0,x0)]\n if len(owners)!=1:return []\n outs=[]\n for own in owners:\n  mask=(g[y0:y1+1,x0:x1+1]==TC).copy()\n  hollow=bool(np.all(mask[0]) and np.all(mask[-1]) and np.all(mask[:,0]) and np.all(mask[:,-1]) and not np.any(mask[1:-1,1:-1]))\n  if trim and hollow:\n   far_y=h-1 if own[2]==1 else 0;far_x=w-1 if own[3]==1 else 0\n   mask[far_y,1:-1]=False;mask[1:-1,far_x]=False\n  out=g.copy();out[out==TC]=BG;good=True\n  for t in triples:\n   oy,ox=_origin(t,h,w)\n   if not (0<=oy and oy+h<=H and 0<=ox and ox+w<=W):good=False;break\n   sh=mask\n   if t[2]!=own[2]:sh=sh[::-1,:]\n   if t[3]!=own[3]:sh=sh[:,::-1]\n   for i,j in np.argwhere(sh):\n    if out[oy+i,ox+j]==DC:good=False;break\n    out[oy+i,ox+j]=TC\n   if not good:break\n  if good:outs.append(out.tolist())\n return outs\n\ndef solve(demonstrations,grid):\n rules=[False,True]\n for d in demonstrations or []:\n  gi,go=(d['input'],d['output']) if isinstance(d,dict) else d\n  rules=[r for r in rules if go in _outputs(gi,r)]\n  if not rules:return None\n outs=[o for r in rules for o in _outputs(grid,r)]\n if not outs or any(o!=outs[0] for o in outs):return None\n return outs[0]\n"
    return source.replace('__BG__',str(palette[0])).replace('__TC__',str(palette[2])).replace('__DC__',str(palette[4]))
